#!/usr/bin/env python3
"""Write ext/SYNC-TO-REPO.md: the exact public-copy list for the pnm/qoi/farbfeld adapters (public witnesses only)."""
import json, sys
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent
L = ['# Public repository copy manifest: PNM, QOI, farbfeld adapters', '',
     'Copy these paths from `/home/ws/projects/leniency/`, preserving relative paths. Every input was generated by code (no third-party corpus bytes).',
     'The `*-PUBLIC` files and witnesses below exclude every input on which any decoder crashed or timed out. The coordinator performs the copy.', '',
     '## Harness', '']
fixed = ['ext/README.md', 'ext/Cargo.toml', 'ext/Cargo.lock', 'ext/build.sh', 'ext/gdk.c', 'ext/qoi_ref.c', 'ext/ff_oracle.py', 'ext/common.py', 'ext/make_sync.py', 'ext/confirm_anomalies.py', 'ext/src/main.rs']
for f in ('pnm', 'qoi', 'farbfeld'):
    fixed += [f'{f}/harness.py', f'{f}/run.sh', f'{f}/reproduce.py', f'{f}/tests/test_{f}.py', f'{f}/summary-public.json', f'{f}/LENIENCY-PUBLIC.md']
L += [f'- `{p}`' for p in fixed]
for f in ('pnm', 'qoi', 'farbfeld'):
    s = json.loads((ROOT / f / 'summary-public.json').read_text())
    L += ['', f'## Public {f} witnesses', ''] + [f'- `{f}/{r["witness"]}`' for r in s['rows']]
L += ['', '## Do not copy', '',
      '- `pnm|qoi|farbfeld/summary.json` and `LENIENCY.md` (local view: crash counts, anomaly ids, all witnesses)',
      '- any witness not listed above, `__pycache__`, anything under `/tmp/claude-0/` (inputs, manifests, per-input results, anomalies, build outputs, the fetched phoboslab/qoi checkout)', '']
(ROOT / 'ext' / 'SYNC-TO-REPO.md').write_text('\n'.join(L))
